import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

/**
 * The icons and the mark are generated by `pnpm brand:assets` and committed, so
 * a broken or missing file would only show up in a browser. These assertions
 * keep the pipeline's output honest without launching one.
 */
const ROOT = join(import.meta.dirname, "../../..");

function bytes(path: string): Buffer {
  return readFileSync(join(ROOT, path));
}

describe("brand assets", () => {
  it("ships the mark as the single vector source", () => {
    const mark = readFileSync(join(ROOT, "public/brand/mark.svg"), "utf8");
    expect(mark).toContain("linearGradient");
    expect(mark).toContain('viewBox="0 0 32 32"');
  });

  it("serves a multi-resolution favicon", () => {
    const ico = bytes("app/favicon.ico");
    expect(ico.readUInt16LE(0)).toBe(0);
    expect(ico.readUInt16LE(2)).toBe(1);
    expect(ico.readUInt16LE(4)).toBe(3);
  });

  it("ships the apple touch icon and the manifest icon set", () => {
    for (const path of [
      "app/apple-icon.png",
      "public/brand/icons/icon-192.png",
      "public/brand/icons/icon-512.png",
      "public/brand/icons/icon-maskable-512.png",
    ]) {
      const png = bytes(path);
      expect(png.subarray(1, 4).toString()).toBe("PNG");
    }
  });

  it("serves the same mark through the icon route", () => {
    expect(readFileSync(join(ROOT, "app/icon.svg"), "utf8")).toBe(
      readFileSync(join(ROOT, "public/brand/mark.svg"), "utf8"),
    );
  });
});
